class Solution:

	def minCoins(self, coins, M, V):
		(n, sm) = (M, V)
		arr = coins
		dp = [[float('inf') for i in range(sm + 1)] for j in range(n + 1)]
		for i in range(n + 1):
			dp[i][0] = 0
		for i in range(1, n + 1):
			for j in range(1, sm + 1):
				if j < arr[i - 1]:
					dp[i][j] = dp[i - 1][j]
				else:
					dp[i][j] = min(1 + dp[i][j - arr[i - 1]], dp[i - 1][j])
		return dp[n][sm] if dp[n][sm] != float('inf') else -1
